function openGroup(){openModal('Novo grupo ou canal','Cadastre um destino do WhatsApp ou Telegram.',field('Nome','name','text','required')+select('Plataforma','platform','<option value="WHATSAPP">WhatsApp</option><option value="TELEGRAM">Telegram</option>')+select('Categoria','categoryId',catOpts())+field('Link de convite','inviteUrl','url','placeholder="https://..."')+'<div class="formgrid">'+field('Membros','members','number','min="0" value="0"')+field('Capacidade','capacity','number','min="1" value="1024"')+'</div>'+field('ID oficial do destino','externalId','text','placeholder="Telegram: -1001234567890"'),async function(e){e.preventDefault();try{await call('POST',Object.assign({entity:'group'},Object.fromEntries(new FormData(e.target))));closeModal();toast('Destino salvo')}catch(err){toast(err.message)}})}
